/**
 * 厂商品牌图标（对话选择器 + 设置页共用）
 * 路径取自各官方标识的常用 SVG 矢量（Simple Icons / 官方 wordmark 图标），
 * 用 currentColor 着色，便于浅色玻璃 / 深色金属主题统一。
 */
import type { ProviderConfig } from '../../shared/types'
import './ProviderBrandIcon.css'

export type ProviderBrand =
  | 'deepseek'
  | 'xai'
  | 'openai'
  | 'kimi'
  | 'zhipu'
  | 'generic'

/** 根据 provider id / baseUrl / model 识别厂商 */
export function detectProviderBrand(provider: Pick<ProviderConfig, 'id' | 'baseUrl' | 'model' | 'name'>): ProviderBrand {
  const id = (provider.id ?? '').toLowerCase()
  const host = (() => {
    try {
      let b = (provider.baseUrl ?? '').trim()
      if (!b.startsWith('http')) b = `https://${b}`
      return new URL(b).hostname.toLowerCase()
    } catch {
      return ''
    }
  })()
  const model = (provider.model ?? '').toLowerCase()
  const name = (provider.name ?? '').toLowerCase()

  if (id === 'deepseek' || host.includes('deepseek') || model.startsWith('deepseek') || name.includes('deepseek')) {
    return 'deepseek'
  }
  if (id === 'xai-grok' || host.includes('x.ai') || model.startsWith('grok') || name.includes('grok') || name.includes('xai')) {
    return 'xai'
  }
  if (
    id === 'openai-chatgpt' ||
    host.includes('openai.com') ||
    host.includes('chatgpt.com') ||
    model.startsWith('gpt-') ||
    /^o[1-9]/.test(model) ||
    name.includes('chatgpt') ||
    name.includes('openai')
  ) {
    return 'openai'
  }
  if (
    id === 'kimi' ||
    host.includes('moonshot') ||
    host.includes('kimi') ||
    model.startsWith('kimi') ||
    model.startsWith('moonshot') ||
    name.includes('kimi') ||
    name.includes('moonshot')
  ) {
    return 'kimi'
  }
  if (
    id === 'zhipu-coding' ||
    host.includes('bigmodel') ||
    host.includes('zhipu') ||
    model.startsWith('glm') ||
    name.includes('智谱') ||
    name.includes('zhipu')
  ) {
    return 'zhipu'
  }
  return 'generic'
}

interface Props {
  provider?: Pick<ProviderConfig, 'id' | 'baseUrl' | 'model' | 'name'> | null
  brand?: ProviderBrand
  size?: number
  className?: string
}

/** 厂商彩色图标 */
export function ProviderBrandIcon({ provider, brand, size = 18, className = '' }: Props) {
  const b = brand ?? (provider ? detectProviderBrand(provider) : 'generic')
  return (
    <span
      className={`provider-brand-icon provider-brand-icon--${b} ${className}`.trim()}
      style={{ width: size, height: size }}
      aria-hidden
    >
      {b === 'deepseek' ? <DeepSeekMark /> : null}
      {b === 'xai' ? <XaiMark /> : null}
      {b === 'openai' ? <OpenAiMark /> : null}
      {b === 'kimi' ? <KimiMark /> : null}
      {b === 'zhipu' ? <ZhipuMark /> : null}
      {b === 'generic' ? <GenericBot /> : null}
    </span>
  )
}

